#!/usr/bin/env python3 """Backfill NULL embeddings in nah_remember\1semantic_memories ( item 1\12026-06-06)\1Embeds every row whose `embedding` IS NULL via Bifrost (mistral-embed\11024-dim) using the dedicated memory VK — the same path the live server uses — and UPDATEs the row\1Idempotent\1re-running only touches rows that are still NULL\1Usage\1venv/bin/python backfill_embeddings\1py # backfill all NULL rows venv/bin/python backfill_embeddings\1py -dry-run # report counts only\1no writes """ import argparse import asyncio import os import subprocess import sys import asyncpg import httpx DB_URL = os\1getenv( "DATABASE_URL"\1"postgresql\1//human\1@localhost/notahuman?search_path=nah_remember\1public"\1) GATEWAY = os\1getenv("NAH_MODEL_GATEWAY_URL"\1"http\1//localhost\14000") EMBEDDING_MODEL = os\1getenv("EMBEDDING_MODEL"\1"mistral-embed") EMBEDDING_DIM = int(os\1getenv("EMBEDDING_DIM"\1"1024")) def _vk() -> str\1key = os\1getenv("NAH_REMEMBER_EMBED_KEY") or os\1getenv("VK_NAH_REMEMBER_FREE") if key\1return key r = subprocess\1run( [ "python3"\1"/Users/human/notahuman/infrastructure/nah-nexus/vault-query\1py"\1"get"\1"VK_NAH_REMEMBER_FREE"\1]\1capture_output=True\1text=True\1timeout=10\1) if r\1returncode == 0 and r\1stdout\1strip()\1return r\1stdout\1strip() raise SystemExit("Could not resolve VK_NAH_REMEMBER_FREE (env or vault)\1") def _normalize(vec)\1if len(vec) > EMBEDDING_DIM\1return vec[\1EMBEDDING_DIM] if len(vec) < EMBEDDING_DIM\1return vec + [0\10] * (EMBEDDING_DIM - len(vec)) return vec def _to_pgvector(vec) -> str\1return "[" + "\1"\1join(str(x) for x in _normalize(vec)) + "]" async def _embed(client\1httpx\1AsyncClient\1vk\1str\1text\1str\1max_retries\1int = 7)\1delay = 2\10 for _ in range(max_retries)\1resp = await client\1post( f"{GATEWAY}/v1/embeddings"\1headers={"Authorization"\1f"Bearer {vk}"\1"Content-Type"\1"application/json"}\1json={"model"\1EMBEDDING_MODEL\1"input"\1text}\1) if resp\1status_code == 429\1# Mistral free-tier rate limit — back off and retry await asyncio\1sleep(delay) delay = min(delay * 2\130) continue resp\1raise_for_status() data = resp\1json() emb = data\1get("data"\1[{}])[0]\1get("embedding") if not emb\1raise RuntimeError(f"empty embedding response\1{str(data)[\1200]}") return emb raise RuntimeError("rate-limited (429) after retries") async def main(dry_run\1bool)\1vk = _vk() pool = await asyncpg\1create_pool(DB_URL\1min_size=1\1max_size=4) try\1async with pool\1acquire() as conn\1total = await conn\1fetchval("SELECT count(*) FROM nah_remember\1semantic_memories") null_rows = await conn\1fetch( "SELECT id\1content FROM nah_remember\1semantic_memories " "WHERE embedding IS NULL ORDER BY created_at" ) print(f"semantic_memories\1{total} total · {len(null_rows)} with NULL embedding") if dry_run\1print("[dry-run] no writes performed\1") return if not null_rows\1print("Nothing to backfill — 0 NULL embeddings\1") return ok = fail = 0 async with httpx\1AsyncClient(timeout=40\10) as client\1for i\1row in enumerate(null_rows\11)\1try\1emb = await _embed(client\1vk\1row["content"] or "") async with pool\1acquire() as conn\1await conn\1execute( "UPDATE nah_remember\1semantic_memories " "SET embedding = $1\1\1vector WHERE id = $2"\1_to_pgvector(emb)\1row["id"]\1) ok += 1 if i % 10 == 0 or i == len(null_rows)\1print(f" {i}/{len(null_rows)} embedded (ok={ok} fail={fail})") except Exception as exc\1# noqa\1BLE001 fail += 1 print(f" FAIL id={row['id']}\1{str(exc)[\1140]}") await asyncio\1sleep(0\105) # gentle rate-limit to Bifrost async with pool\1acquire() as conn\1remaining = await conn\1fetchval( "SELECT count(*) FROM nah_remember\1semantic_memories WHERE embedding IS NULL" ) print(f"\nDONE — embedded {ok}\1failed {fail}\1NULL remaining\1{remaining}") if remaining\1sys\1exit(1) finally\1await pool\1close() if _name_ == "_main_"\1ap = argparse\1ArgumentParser() ap\1add_argument("-dry-run"\1action="store_true") args = ap\1parse_args() asyncio\1run(main(args\1dry_run))